class Poll:
    def __init__(self, question: str) -> None:
        self.question = question
        self.options: list[str] = []
        self.votes: dict[str, int] = {}
        self.voters: set[str] = set()

    def add_option(self, option: str) -> None:
        if option not in self.votes:
            self.options.append(option)
            self.votes[option] = 0

    def vote(self, voter: str, option: str) -> None:
        if voter in self.voters:
            raise ValueError(f"Voter '{voter}' has already voted.")
        if option not in self.votes:
            raise ValueError(f"Option '{option}' does not exist.")

        self.voters.add(voter)
        self.votes[option] += 1

    def winner(self) -> str | None:
        if not self.options:
            return None

        # Iterate in reverse order so that later added options take precedence in ties
        best_option = None
        max_votes = -1

        for option in reversed(self.options):
            vote_count = self.votes[option]
            if vote_count > max_votes:
                max_votes = vote_count
                best_option = option

        return best_option
